// Décide si on lance la recherche aujourd'hui.
// - Planning : on lance, sauf si déjà fait aujourd'hui.
// - Démarrage du PC (rattrapage) : on lance seulement si l'heure prévue est passée
//   ET que rien n'a encore tourné aujourd'hui (PC éteint à l'heure prévue).
// La date du dernier lancement est gardée dans les "static data" du workflow.
const HEURE_PREVUE = 14; // ⚠️ même heure que le nœud « Programmation »
const memoire = $getWorkflowStaticData('global');
const aujourdhui = $now.toFormat('yyyy-MM-dd'); // fuseau : Settings du workflow
const rattrapage = $('Démarrage de n8n').isExecuted;

if (memoire.dernierLancement === aujourdhui) return [];       // déjà fait aujourd'hui
if (rattrapage && $now.hour < HEURE_PREVUE) return [];        // le planning s'en chargera

memoire.dernierLancement = aujourdhui;
return [{ json: { declencheur: rattrapage ? 'rattrapage au démarrage' : 'planning', date: aujourdhui } }];

// ⚙️ PARAMÈTRES — le SEUL nœud à modifier.
// Le métier, le niveau, le pays et les mots-clés de recherche sont lus automatiquement
// dans ton CV par Gemini (nœuds « Gemini lit le CV » et « Profil du CV »). Tu peux les forcer ici si tu veux.
return [{ json: {
  email: 'TON_EMAIL@gmail.com',           // où recevoir l'email du jour
  modeleCV: 'COLLE_ICI_LE_LIEN_DE_TON_MODELE_DE_CV_GOOGLE_DOCS',  // Google Doc avec les marqueurs {{CLÉ: texte}}
  sheet: 'COLLE_ICI_LE_LIEN_DE_TON_GOOGLE_SHEET',     // Google Sheet vide avec un onglet nommé « Offres »

  scoreMinimum: 60,       // note minimale (0-100) pour qu'une offre soit envoyée
  offresParJour: 3,       // nombre d'offres envoyées par jour (avec CV adapté)
  offresAnalysees: 12,    // offres notées par Gemini par jour (max ~12 : Gemini gratuit = 15 requêtes/min)
  maxJours: 21,           // ignorer les offres publiées il y a plus de N jours

  // Optionnel : laisser vide = déduit du CV
  motsCles: [],           // ex. ['devops', 'cloud engineer']
  pays: '',               // code pays à 2 lettres pour JSearch, ex. 'ma', 'fr', 'de', 'ca'
} }];

// Lit le modèle de CV (réponse brute de l'API Google Docs) :
// 1) tout le texte, y compris dans les tableaux -> cvTexte (sert à Gemini pour noter les offres)
// 2) les marqueurs {{CLÉ: texte original}} -> champs (ce que Gemini a le droit d'adapter)
const doc = $input.first().json;
let texte = '';
const lire = contenu => {
  for (const bloc of contenu || []) {
    if (bloc.paragraph) for (const el of bloc.paragraph.elements || []) texte += el.textRun?.content || '';
    if (bloc.table) for (const ligne of bloc.table.tableRows || []) for (const cellule of ligne.tableCells || []) lire(cellule.content);
    if (bloc.tableOfContents) lire(bloc.tableOfContents.content);
  }
};
lire(doc.body?.content);

const marqueur = /\{\{([A-Z0-9_]+):\s?([^{}\n\u000b]+?)\}\}/g;
const champs = {}, marqueurs = {};
for (const m of texte.matchAll(marqueur)) {
  champs[m[1]] = m[2].trim();
  marqueurs[m[1]] = m[0];            // texte exact à remplacer dans la copie du modèle
}
if (Object.keys(champs).length === 0) {
  throw new Error("Aucun marqueur {{CLÉ: texte}} trouvé dans le modèle de CV. Vérifie le lien dans « Paramètres » et le format des marqueurs (voir le guide).");
}
const cvTexte = texte.replace(marqueur, (_, cle, valeur) => valeur.trim());
return [{ json: { cvTexte, champs, marqueurs, nbChamps: Object.keys(champs).length } }];

// Lit l'analyse du CV par Gemini, et applique les choix forcés dans « Paramètres ».
const p = $('Paramètres').first().json;
const t = ($input.first().json.text || '').replace(/```[a-z]*/g, '');
let a = {};
try { a = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) {
  throw new Error("Gemini n'a pas renvoyé une analyse lisible du CV : " + t.slice(0, 300));
}
const liste = x => (Array.isArray(x) ? x : []).map(s => String(s).toLowerCase().trim()).filter(Boolean);
const motsCles = (p.motsCles && p.motsCles.length) ? p.motsCles : (a.mots_cles || []);
return [{ json: {
  prenom: a.prenom || '',
  metier: a.metier || '',
  niveau: a.niveau || '',
  annees_experience: a.annees_experience ?? '',
  pays_code: (p.pays || a.pays_code || '').toLowerCase(),
  pays_nom: a.pays_nom || '',
  langue: a.langue === 'en' ? 'en' : 'fr',
  mots_cles: motsCles.slice(0, 4),
  mots_titre: liste(a.mots_titre).concat(liste(motsCles)),
  mots_exclus: liste(a.mots_exclus),
  profil: a.profil || '',
} }];

// Une recherche JSearch par mot-clé (Google for Jobs : LinkedIn, Indeed, sites locaux...).
// 4 recherches par jour x 30 jours = 120 requêtes/mois : ça tient dans le plan gratuit JSearch (200).
const a = $('Profil du CV').first().json;
return a.mots_cles.map(k => ({ json: { query: `${k} ${a.pays_nom}`.trim() } }));

// JSearch renvoie une réponse par recherche, avec une liste d'offres dedans.
// 1) on met toutes les offres à plat
// 2) filtre gratuit avant Gemini (Gemini gratuit = 15 requêtes/minute) : métier, niveau, date, doublons
const p = $('Paramètres').first().json;
const a = $('Profil du CV').first().json;

// "il y a 3 jours" / "3 days ago" -> date (JSearch ne donne pas toujours la vraie date)
const dateDepuis = texte => {
  const m = String(texte || '').match(/(\d+)\s*(minute|heure|hour|jour|day|semaine|week|mois|month)/i);
  if (!m) return '';
  const unite = { minute: 1 / 1440, heure: 1 / 24, hour: 1 / 24, jour: 1, day: 1, semaine: 7, week: 7, mois: 30, month: 30 };
  return new Date(Date.now() - unite[m[2].toLowerCase()] * Number(m[1]) * 86400000).toISOString().slice(0, 10);
};
const offres = [];
for (const reponse of $input.all()) {
  for (const j of (reponse.json.data?.jobs || [])) {
    offres.push({
      job_id: j.job_id,
      job_title: (j.job_title || '').trim(),
      company: (j.employer_name || '').trim(),
      location: String(j.job_location || '').split('•')[0].replace(/\s+/g, ' ').trim(),
      job_url: j.job_apply_link || j.job_google_link || '',
      apply_url: j.job_apply_link || '',
      description: j.job_description || '',
      posted_at: j.job_posted_at_datetime_utc ? String(j.job_posted_at_datetime_utc).slice(0, 10) : dateDepuis(j.job_posted_at),
      work_type: (j.job_employment_types || []).join(', '),
      salary: j.job_salary_string || '',
      source: j.job_publisher || '',
    });
  }
}

// Mots lus dans le CV par Gemini -> filtres sur le titre
const echapper = s => s.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&');
const motif = mots => mots.length ? new RegExp('(' + mots.map(echapper).join('|') + ')', 'i') : null;
const metier = motif(a.mots_titre);
const exclus = motif(a.mots_exclus);
const debutant = /junior|débutant|jeune diplômé|entry level|graduate/i;

// Même clé que pour les doublons : premier mot de l'entreprise + titre
const cle = (entreprise, titre) =>
  (entreprise || '').toLowerCase().split(' ')[0] + '|' +
  (titre || '').replace(/[​-‍﻿]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();

// Offres déjà dans le Sheet (déjà envoyées un autre jour) : on ne les renvoie pas
const vus = new Set();
for (const ligne of $('Lire le Sheet').all()) {
  const l = ligne.json;
  if (l['Titre']) vus.add(cle(l['Entreprise'], l['Titre']));
  if (l['Lien offre']) vus.add(String(l['Lien offre']).trim());
}

const gardees = [];
for (const o of offres) {
  if (metier && !metier.test(o.job_title)) continue;
  // "Junior à Senior" : pour un candidat junior, le mot junior l'emporte
  if (exclus && exclus.test(o.job_title) && !(a.niveau === 'junior' && debutant.test(o.job_title))) continue;
  if (o.description.length < 300) continue; // annonces vides (agrégateurs)
  const jours = (Date.now() - new Date(o.posted_at)) / 86400000;
  if (o.posted_at && !(jours <= p.maxJours)) continue;
  const k = cle(o.company, o.job_title);
  if (vus.has(k) || vus.has(String(o.job_url).trim())) continue;
  vus.add(k);
  gardees.push(o);
}

// Les plus récentes d'abord
return gardees
  .sort((x, y) => String(y.posted_at).localeCompare(String(x.posted_at)))
  .slice(0, p.offresAnalysees)
  .map(o => ({ json: o }));

