// Lit la réponse de Gemini (score + raison) et la colle à l'offre,
// pour que la sortie "done" de la boucle contienne toutes les infos.
const offre = $('Nettoyer les offres').item.json;
const t = ($input.item.json.text || '').replace(/```[a-z]*/g, '');
let r = {};
try {
  r = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
} catch (e) {
  // Gemini met parfois des guillemets dans la raison, ce qui casse le JSON : on lit champ par champ
  const score = t.match(/"score"\s*:\s*"?(\d+)/);
  const raison = t.match(/"reason"\s*:\s*"([\s\S]*)"\s*\}/);
  r = { score: score ? score[1] : 0, reason: raison ? raison[1] : '' };
}
return { json: { ...offre, score: Number(r.score) || 0, reason: r.reason || '' } };

// Garde les meilleures offres du jour (nombre et score minimum dans « Paramètres »).
// Mieux vaut moins d'offres que des offres qui ne correspondent pas.
const p = $('Paramètres').first().json;
return $input.all()
  .map(i => i.json)
  .filter(o => o.job_title && o.score >= p.scoreMinimum)
  .sort((a, b) => b.score - a.score)
  .slice(0, p.offresParJour)
  .map(o => ({ json: o }));

