// Lit le JSON renvoyé par Gemini. Si un champ manque ou est vide,
// on garde le texte original : le CV ne doit jamais avoir de marqueur {{...}} visible.
// Prépare aussi les remplacements pour la copie du modèle.
const cv = $('Préparer le CV').first().json;
const original = cv.champs;

const texte = ($input.item.json.text || '').replace(/```[a-z]*/g, '').replace(/\r?\n/g, ' ').trim();
let adapte = {};
try {
  adapte = JSON.parse(texte.slice(texte.indexOf('{'), texte.lastIndexOf('}') + 1));
} catch (e) {
  adapte = {};
}

const resultat = {};
for (const cle of Object.keys(original)) {
  const v = typeof adapte[cle] === 'string' ? adapte[cle].replace(/\s*\n\s*/g, ' ').replace(/^[•\-–]\s*/, '').trim() : '';
  resultat[cle] = v || original[cle];
}
// Garde-fou anti-invention : chaque mot du texte adapté doit exister quelque part dans le CV d'origine
// (sauf les petits mots de liaison). Sinon on garde le texte original de ce champ.
const normaliser = s => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[’']/g, ' ');
const racine = m => m.length > 3 ? m.replace(/(s|x)$/, '') : m;   // pluriel ≈ singulier
const mots = s => (normaliser(s).match(/[a-z0-9+#.]+/g) || []).map(m => racine(m.replace(/\.+$/, ''))).filter(Boolean);
const liaison = new Set(('a au aux avec ce ces cette d dans de des du en et j je l la le les leur ma mes mon ne ou par pour qu que qui sa se ses son sur un une y '
  + 'an and as at by for from i in into is my of on or the to with').split(' '));
const vocabulaire = new Set(mots(cv.cvTexte));
const refuses = [];
for (const cle of Object.keys(original)) {
  const inconnus = [...new Set(mots(resultat[cle]).filter(m => !liaison.has(m) && !vocabulaire.has(m)))];
  if (inconnus.length) { refuses.push(`${cle} (${inconnus.join(', ')})`); resultat[cle] = original[cle]; }
}
// Compétences : Gemini peut changer l'ordre, mais pas la liste. Sinon on garde l'original.
const items = s => s.split(',').map(x => x.trim()).filter(Boolean).sort().join('|');
for (const cle of Object.keys(original).filter(k => k.startsWith('COMP'))) {
  if (items(resultat[cle]) !== items(original[cle])) resultat[cle] = original[cle];
}
const requetes = Object.keys(original).map(cle => ({
  replaceAllText: { containsText: { text: cv.marqueurs[cle], matchCase: true }, replaceText: resultat[cle] },
}));
return { json: { ...resultat, json_ok: Object.keys(adapte).length > 0, champs_refuses: refuses, requetes } };

// Résumé du jour : une carte par offre envoyée, avec le lien du CV.
// Si aucune offre n'a passé le score minimum, "Top du jour" est vide et rien n'arrive ici : pas d'email.
const offres = $('Top du jour').all().map(i => i.json);
const cvs = $('Copier le modèle').all().map(i => i.json.id);
const a = $('Profil du CV').first().json;
if (offres.length === 0) return [];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cartes = offres.map((o, n) => {
  const cv = `https://docs.google.com/document/d/${cvs[n]}/edit`;
  const pdf = `https://docs.google.com/document/d/${cvs[n]}/export?format=pdf`;
  return `<div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:12px 0">
  <span style="background:#eef;border-radius:4px;padding:1px 6px">${esc(o.score)}/100 · via ${esc(o.source)}</span><br>
  <b>${n + 1}. ${esc(o.job_title)}</b> — ${esc(o.company)} <span style="color:#666">${esc(o.location)}</span><br>
  ${o.reason ? `<i style="color:#444">${esc(o.reason)}</i><br>` : ''}
  <a href="${esc(pdf)}">📄 Télécharger le CV (PDF)</a> &nbsp;·&nbsp; <a href="${esc(cv)}">✏️ Ouvrir le CV</a>
  &nbsp;·&nbsp; <a href="${esc(o.apply_url || o.job_url)}"><b>✅ Postuler</b></a>
</div>`;
}).join('\n');

const s = offres.length > 1 ? 's' : '';
const html = `<p>Bonjour ${esc(a.prenom)} 👋</p>
<p>${offres.length} offre${s} « ${esc(a.metier)} » (${esc(a.pays_nom)}) pour toi aujourd'hui, CV déjà adapté.
Relis le CV → clique sur Postuler.</p>
${cartes}
<p style="color:#666">Toutes les offres envoyées sont aussi dans ton Google Sheet.</p>`;

return [{ json: { subject: `🎯 ${offres.length} offre${s} ${a.metier} — CV adapté`, html } }];
